// routes/_middleware.dart
import 'package:dart_frog/dart_frog.dart';
import 'package:myapp/myapp.dart';

Handler middleware(Handler handler) {
  return handler
      .use(requestLogger())
      .use(provider<Config>((_) => Config.fromEnvironment()))
      .use(provider<Database>((ctx) =>
          Database(ctx.read<Config>().dbUrl)))
      .use(provider<UserRepository>((ctx) =>
          UserRepositoryImpl(ctx.read<Database>())))
      .use(provider<UserService>((ctx) =>
          UserService(ctx.read<UserRepository>(), ctx.read<Config>())))
      .use(errorHandler());
}

// routes/api/v1/users/index.dart
import 'dart:io';
import 'package:dart_frog/dart_frog.dart';
import 'package:myapp/myapp.dart';

Future<Response> onRequest(RequestContext context) async {
  return switch (context.request.method) {
    HttpMethod.get  => _handleGet(context),
    HttpMethod.post => _handlePost(context),
    _               => Future.value(Response(statusCode: HttpStatus.methodNotAllowed)),
  };
}

Future<Response> _handleGet(RequestContext context) async {
  final service = context.read<UserService>();
  final page    = int.tryParse(
      context.request.uri.queryParameters['page'] ?? '1') ?? 1;
  final limit   = int.tryParse(
      context.request.uri.queryParameters['limit'] ?? '20') ?? 20;
  final users   = await service.getAll(page: page, limit: limit);
  return Response.json({'users': users.map((u) => u.toJson()).toList(),
                        'meta': {'page': page, 'limit': limit}});
}

Future<Response> _handlePost(RequestContext context) async {
  final service = context.read<UserService>();
  final body    = await context.request.json() as Map<String, dynamic>;
  final user    = await service.create(body);
  return Response.json(user.toJson(), statusCode: HttpStatus.created);
}

// routes/api/v1/users/[id].dart
import 'dart:io';
import 'package:dart_frog/dart_frog.dart';
import 'package:myapp/myapp.dart';

Future<Response> onRequest(RequestContext context, String id) async {
  return switch (context.request.method) {
    HttpMethod.get    => _get(context, id),
    HttpMethod.put    => _update(context, id),
    HttpMethod.delete => _delete(context, id),
    _                 => Future.value(Response(statusCode: HttpStatus.methodNotAllowed)),
  };
}

Future<Response> _get(RequestContext context, String id) async {
  final user = await context.read<UserService>().getById(id);
  return Response.json(user.toJson());
}

Future<Response> _update(RequestContext context, String id) async {
  final body = await context.request.json() as Map<String, dynamic>;
  final user = await context.read<UserService>().update(id, body);
  return Response.json(user.toJson());
}

Future<Response> _delete(RequestContext context, String id) async {
  await context.read<UserService>().delete(id);
  return Response(statusCode: HttpStatus.noContent);
}

// lib/src/middleware/error_handler.dart
import 'dart:io';
import 'package:dart_frog/dart_frog.dart';
import 'package:myapp/src/exceptions.dart';

Middleware errorHandler() {
  return (handler) {
    return (context) async {
      try {
        return await handler(context);
      } on ValidationException catch (e) {
        return Response.json(
          {'error': e.message, 'errors': e.errors},
          statusCode: HttpStatus.unprocessableEntity,
        );
      } on NotFoundException catch (e) {
        return Response.json(
          {'error': e.message}, statusCode: HttpStatus.notFound);
      } on UnauthorizedException catch (e) {
        return Response.json(
          {'error': e.message}, statusCode: HttpStatus.unauthorized);
      } on ForbiddenException catch (e) {
        return Response.json(
          {'error': e.message}, statusCode: HttpStatus.forbidden);
      } catch (e, stack) {
        print('Unhandled error: $e\n$stack');
        return Response.json(
          {'error': 'Internal server error'},
          statusCode: HttpStatus.internalServerError,
        );
      }
    };
  };
}

// lib/src/exceptions.dart
class AppException implements Exception {
  final String message;
  const AppException(this.message);
}

class ValidationException extends AppException {
  final Map<String, List<String>> errors;
  const ValidationException(super.message, [this.errors = const {}]);
}

class NotFoundException extends AppException {
  const NotFoundException(super.message);
}

class UnauthorizedException extends AppException {
  const UnauthorizedException([super.message = 'Unauthorized']);
}

class ForbiddenException extends AppException {
  const ForbiddenException([super.message = 'Forbidden']);
}

// lib/src/models/user.dart
@freezed
class User with _$User {
  const User._();
  const factory User({
    required String id,
    required String email,
    required String name,
    @Default(false) bool isAdmin,
    @JsonKey(includeToJson: false) String? passwordHash,
    required DateTime createdAt,
    DateTime? updatedAt,
  }) = _User;

  factory User.fromJson(Map<String, dynamic> json) => _$UserFromJson(json);
}

// test/routes/api/v1/users/index_test.dart
import 'dart:io';
import 'package:dart_frog/dart_frog.dart';
import 'package:test/test.dart';
import 'package:mocktail/mocktail.dart';
import 'package:myapp/myapp.dart';

// Import the route handler under test
import '../../../../../routes/api/v1/users/index.dart' as route;

class MockRequestContext extends Mock implements RequestContext {}
class MockUserService    extends Mock implements UserService {}

void main() {
  late MockRequestContext context;
  late MockUserService    userService;

  setUp(() {
    context     = MockRequestContext();
    userService = MockUserService();
    when(() => context.read<UserService>()).thenReturn(userService);
  });

  test('GET returns users list with 200', () async {
    when(() => userService.getAll(
          page: any(named: 'page'), limit: any(named: 'limit')))
        .thenAnswer((_) async => []);
    when(() => context.request).thenReturn(
      Request('GET', Uri.parse('http://localhost/api/v1/users')),
    );

    final response = await route.onRequest(context);
    expect(response.statusCode, equals(HttpStatus.ok));
  });

  test('POST creates user and returns 201', () async {
    when(() => userService.create(any())).thenAnswer((_) async => mockUser);
    when(() => context.request).thenReturn(
      Request('POST', Uri.parse('http://localhost/api/v1/users'),
              body: '{"email":"a@b.com","name":"Test","password":"secret"}'),
    );

    final response = await route.onRequest(context);
    expect(response.statusCode, equals(HttpStatus.created));
  });

  test('DELETE returns 405 for unsupported method', () async {
    when(() => context.request).thenReturn(
      Request('DELETE', Uri.parse('http://localhost/api/v1/users')),
    );
    final response = await route.onRequest(context);
    expect(response.statusCode, equals(HttpStatus.methodNotAllowed));
  });
}
